#!/usr/bin/env node
// The asynchronous export at full scale on the synthetic load dataset (ADR-0058 §7; REQ-S20-030; T-DG6-BE-S).
//
//   node deploy/load/export-proof.mjs --sessions "$TMPDIR/sessions.json" --base-url http://127.0.0.1:<port> \
//     --db-url postgresql://…/mth --out "$TMPDIR/export-proof.json" [--label run-1] [--poll-ms 250] [--timeout-s 900]
//
// Runs against a load database (generated by deploy/load/generate.mjs, sessions minted by deploy/load/sessions.mjs,
// the API and the worker running with MTH_ENV=load). It is outside every Vitest project, so `pnpm test:integration`
// never needs the load dataset. It reads the database only in one READ ONLY transaction (the users' assignments and
// the transformations); every export goes through the API exactly as a browser's request would. Exit 0 when every
// assertion holds, 1 when any fails, 2 on a usage or setup error. The output is a JSON report (and a summary on
// stdout); it never contains a cookie or CSRF token.
//
// Part A, the largest transformation LOAD-T01 (250 initiatives): a live selection of every section the export offers
// for it: each report definition whose subject is the transformation and that needs no reporting period, in xlsx and
// in csv where the definition offers the format, and for `registers` each of its six registers. One requester.
// Part B: 50 exports queued at once, one per transformation, by 50 different load users (a matching of users to
// transformations they can export), csv, register `raid`.
//
// Assertions per export (ADR-0058 §7): createExport answers 202 with the job id within 2 s (the ordinary-update
// target); getExport's `percent` never decreases and reaches 100 with status `succeeded`; the requester downloads the
// file (200, non-empty, SHA-256 equal to the job's fileSha256); another load user with the same transformation scope
// gets 404 for getExport and for the download; an AUD user gets 404 for both. The completion time of each job is
// reported (no target). A job that fails with `export.too_large` (EXPORT_MAX_BYTES) is reported as a reopen candidate
// with its measured reason, never changed here. Synthetic data only; nothing here approves anything.
import { createHash } from "node:crypto";
import { writeFileSync, readFileSync } from "node:fs";
import { createRequire } from "node:module";
import { parseArgs } from "node:util";

const requireFromDb = createRequire(new URL("../../packages/db/package.json", import.meta.url));

export const START_TARGET_MS = 2000;
export const REGISTERS = ["raid", "benefits", "kpis", "decisions", "dependencies", "actions"];
const FORMATS = ["xlsx", "csv"];

/** Integer microseconds between two performance.now() readings (as the workload harness measures). */
const micros = (t0, t1) => Math.round((t1 - t0) * 1000);

/** Nearest-rank percentile on integers (rank = ceil(p·n/100)), null when there is no sample. */
export function nearestRank(values, p) {
  if (values.length === 0) return null;
  const sorted = [...values].sort((a, b) => a - b);
  const rank = Math.floor((p * sorted.length + 99) / 100);
  return sorted[Math.max(0, rank - 1)];
}

/** True when the sequence never decreases. */
export function nonDecreasing(seq) {
  for (let i = 1; i < seq.length; i++) if (seq[i] < seq[i - 1]) return false;
  return true;
}

/**
 * A maximum matching of transformations to distinct users (Kuhn's augmenting paths), deterministic: transformations
 * in code order, candidate users in index order. `candidates` maps a transformation id to user indexes.
 */
export function matchUsers(transformationIds, candidates) {
  const owner = new Map(); // user index -> transformation id
  const tryAssign = (t, seen) => {
    for (const u of candidates.get(t) ?? []) {
      if (seen.has(u)) continue;
      seen.add(u);
      if (!owner.has(u) || tryAssign(owner.get(u), seen)) {
        owner.set(u, t);
        return true;
      }
    }
    return false;
  };
  for (const t of transformationIds) tryAssign(t, new Set());
  const byTransformation = new Map();
  for (const [u, t] of owner) byTransformation.set(t, u);
  return byTransformation;
}

// ------------------------------------------------------------------------------------------------------------- HTTP

function client(base, origin) {
  return async function call(session, method, path, { body, idempotencyKey } = {}) {
    const h = { cookie: session.cookie, accept: "application/json", "accept-language": "en" };
    if (method !== "GET") {
      h["x-csrf-token"] = session.csrfToken;
      if (origin) h.origin = origin;
    }
    if (body !== undefined) h["content-type"] = "application/json";
    if (idempotencyKey !== undefined) h["idempotency-key"] = idempotencyKey;
    const t0 = performance.now();
    const res = await fetch(base + path, {
      method,
      headers: h,
      body: body === undefined ? undefined : JSON.stringify(body),
    });
    const buf = Buffer.from(await res.arrayBuffer());
    const us = micros(t0, performance.now());
    let json = null;
    if ((res.headers.get("content-type") ?? "").includes("json")) {
      try {
        json = JSON.parse(buf.toString("utf8"));
      } catch {
        json = null;
      }
    }
    return { status: res.status, us, buf, json };
  };
}

// ----------------------------------------------------------------------------------------------------------- setup

/** Read-only discovery: transformations, report definitions and every load user's transformation-scope grants. */
async function discover(dbUrl, sessions) {
  const { Client } = requireFromDb("pg");
  const c = new Client({ connectionString: dbUrl, application_name: "mth-load export-proof (setup, read-only)" });
  await c.connect();
  try {
    await c.query("BEGIN READ ONLY");
    const marker = (await c.query("SELECT dataset_code, random_seed FROM load_dataset_marker")).rows[0];
    if (!marker) throw new Error("mth-load export-proof: refused: the database holds no load_dataset_marker row");
    const transformations = (await c.query(`SELECT id, code FROM transformation ORDER BY code`)).rows;
    const definitions = (
      await c.query(
        `SELECT code, formats FROM report_definition
          WHERE subject_type = 'transformation' AND needs_reporting_period = false ORDER BY ordinal`,
      )
    ).rows;
    const grants = (
      await c.query(
        `SELECT a.user_id, a.scope_id AS transformation_id,
                bool_or(rp.permission_code = 'export.create') AS can_export,
                bool_or(rp.permission_code = 'report.generate') AS can_report,
                bool_or(rp.permission_code = 'transformation.read') AS can_read
           FROM scoped_assignment a
           LEFT JOIN role_permission rp ON rp.role_id = a.role_id
          WHERE a.user_id = ANY($1::uuid[]) AND a.revoked_at IS NULL AND a.scope_type = 'transformation'
          GROUP BY a.user_id, a.scope_id ORDER BY a.user_id, a.scope_id`,
        [sessions.map((s) => s.userId)],
      )
    ).rows;
    const initiatives = (await c.query(`SELECT transformation_id, count(*)::int AS n FROM initiative GROUP BY 1`)).rows;
    await c.query("COMMIT");
    return { marker, transformations, definitions, grants, initiatives };
  } finally {
    await c.end();
  }
}

// ---------------------------------------------------------------------------------------------------------- one job

/** Creates one export and times the start (the createExport response). */
async function start(call, session, sel, format, key) {
  const r = await call(session, "POST", "/api/v1/exports", {
    body: { format, language: "en", report: sel },
    idempotencyKey: key,
  });
  return { status: r.status, startUs: r.us, job: r.json, problem: r.status === 202 ? null : r.json };
}

/** Polls getExport until a final status; returns the percent sequence and the final job. */
async function follow(call, session, jobId, pollMs, deadline) {
  const percents = [];
  const t0 = performance.now();
  for (;;) {
    const r = await call(session, "GET", `/api/v1/exports/${jobId}`);
    if (r.status !== 200) return { percents, final: null, pollStatus: r.status, doneUs: micros(t0, performance.now()) };
    percents.push(r.json.percent);
    if (["succeeded", "failed", "cancelled"].includes(r.json.status))
      return { percents, final: r.json, pollStatus: 200, doneUs: micros(t0, performance.now()) };
    if (performance.now() > deadline)
      return { percents, final: r.json, pollStatus: "timeout", doneUs: micros(t0, performance.now()) };
    await new Promise((res) => setTimeout(res, pollMs));
  }
}

/** Every ADR-0058 §7 assertion for one export; returns the record with `failures` (empty when it passes). */
async function prove(call, { requester, other, aud }, sel, format, key, pollMs, deadline, startResult) {
  const failures = [];
  const s = startResult ?? (await start(call, requester, sel, format, key));
  const rec = {
    definitionCode: sel.definitionCode,
    register: sel.parameters?.register ?? null,
    format,
    transformationId: sel.subjectId,
    requesterUserId: requester.userId,
    startStatus: s.status,
    startMs: s.startUs / 1000,
    jobId: s.job?.id ?? null,
    failures,
  };
  if (s.status !== 202 || typeof s.job?.id !== "string") {
    failures.push(`createExport ${s.status} ${s.problem?.code ?? ""}`.trim());
    return rec;
  }
  if (s.startUs > START_TARGET_MS * 1000)
    failures.push(`createExport took ${s.startUs / 1000} ms > ${START_TARGET_MS} ms`);
  const f = await follow(call, requester, s.job.id, pollMs, deadline);
  rec.percents = f.percents;
  rec.completionMs = f.doneUs / 1000;
  rec.finalStatus = f.final?.status ?? null;
  rec.errorCode = f.final?.errorCode ?? null;
  rec.fileSizeBytes = f.final?.fileSizeBytes ?? null;
  if (f.pollStatus !== 200) failures.push(`getExport ${f.pollStatus}`);
  if (!nonDecreasing([0, ...f.percents])) failures.push(`percent decreased: ${f.percents.join(",")}`);
  if (f.final?.status !== "succeeded")
    failures.push(`status ${f.final?.status ?? "unknown"} ${rec.errorCode ?? ""}`.trim());
  if (f.percents.at(-1) !== 100) failures.push(`last percent ${f.percents.at(-1)}`);
  if (rec.errorCode === "export.too_large") rec.reopenCandidate = "EXPORT_MAX_BYTES reached (ADR-0058 §7)";
  if (f.final?.status === "succeeded") {
    const d = await call(requester, "GET", `/api/v1/exports/${s.job.id}/download`);
    rec.downloadStatus = d.status;
    rec.downloadBytes = d.buf.length;
    const sha = createHash("sha256").update(d.buf).digest("hex");
    if (d.status !== 200 || d.buf.length === 0) failures.push(`requester download ${d.status} (${d.buf.length} bytes)`);
    else if (sha !== f.final.fileSha256) failures.push("requester download sha256 differs from fileSha256");
  }
  for (const [who, sess] of [
    ["sameScopeOther", other],
    ["aud", aud],
  ]) {
    if (!sess) {
      failures.push(`no ${who} user for this transformation`);
      continue;
    }
    const g = await call(sess, "GET", `/api/v1/exports/${s.job.id}`);
    const d = await call(sess, "GET", `/api/v1/exports/${s.job.id}/download`);
    rec[`${who}UserId`] = sess.userId;
    rec[`${who}Statuses`] = { getExport: g.status, download: d.status };
    if (g.status !== 404) failures.push(`${who} getExport ${g.status} (expected 404)`);
    if (d.status !== 404) failures.push(`${who} download ${d.status} (expected 404)`);
  }
  return rec;
}

// ------------------------------------------------------------------------------------------------------------ main

export async function runProof(opts) {
  const sessionsFile = JSON.parse(readFileSync(opts.sessions, "utf8"));
  const sessions = sessionsFile.sessions;
  const call = client(opts.baseUrl, sessionsFile.appBaseUrl ?? null);
  const d = await discover(opts.dbUrl, sessions);
  const byUserId = new Map(sessions.map((s, i) => [s.userId, { ...s, index: i }]));
  const exporters = new Map(); // transformation id -> [user index]
  const readers = new Map(); // transformation id -> [user index] (same scope, cannot necessarily export)
  for (const g of d.grants) {
    const u = byUserId.get(g.user_id);
    if (!u) continue;
    const put = (m) => {
      if (!m.has(g.transformation_id)) m.set(g.transformation_id, []);
      if (!m.get(g.transformation_id).includes(u.index)) m.get(g.transformation_id).push(u.index);
    };
    if (g.can_read) put(readers);
    if (g.can_export && g.can_report) put(exporters);
  }
  for (const m of [exporters, readers]) for (const list of m.values()) list.sort((a, b) => a - b);
  const isAud = (i) => (sessions[i].roles ?? []).includes("AUD");
  const audAny = sessions.findIndex((s) => (s.roles ?? []).includes("AUD"));
  /** The other same-scope user (not the requester, not AUD) and an AUD user (same scope when there is one). */
  const witnesses = (t, requesterIndex) => {
    const sameScope = (readers.get(t) ?? []).filter((i) => i !== requesterIndex);
    const other = sameScope.find((i) => !isAud(i));
    const aud = sameScope.find((i) => isAud(i)) ?? (audAny >= 0 ? audAny : undefined);
    return {
      other: other === undefined ? null : sessions[other],
      aud: aud === undefined ? null : sessions[aud],
      audSameScope: sameScope.some((i) => isAud(i)),
    };
  };
  const deadline = () => performance.now() + opts.timeoutS * 1000;
  const report = {
    note: "SYNTHETIC load dataset; sandbox measurement, not Mobily production capacity; approves nothing",
    label: opts.label,
    startedAt: new Date().toISOString(),
    dataset: d.marker,
    startTargetMs: START_TARGET_MS,
    partA: null,
    partB: null,
  };

  // Part A: LOAD-T01, every section.
  const t01 = d.transformations.find((t) => t.code === "LOAD-T01");
  if (!t01) throw new Error("mth-load export-proof: no transformation LOAD-T01");
  const reqA = (exporters.get(t01.id) ?? [])[0];
  if (reqA === undefined) throw new Error("mth-load export-proof: no load user can export LOAD-T01");
  const wA = witnesses(t01.id, reqA);
  const selections = [];
  for (const def of d.definitions)
    for (const format of FORMATS) {
      if (!(def.formats ?? []).includes(format)) continue;
      if (def.code === "registers")
        for (const register of REGISTERS)
          selections.push({ sel: { definitionCode: def.code, subjectId: t01.id, parameters: { register } }, format });
      else selections.push({ sel: { definitionCode: def.code, subjectId: t01.id }, format });
    }
  const a = [];
  let n = 0;
  for (const { sel, format } of selections)
    a.push(
      await prove(
        call,
        { requester: sessions[reqA], other: wA.other, aud: wA.aud },
        sel,
        format,
        `mth-proof-${opts.label}-a${n++}`,
        opts.pollMs,
        deadline(),
      ),
    );
  report.partA = {
    transformation: t01.code,
    initiatives: d.initiatives.find((r) => r.transformation_id === t01.id)?.n ?? null,
    requesterUserId: sessions[reqA].userId,
    sameScopeOtherUserId: wA.other?.userId ?? null,
    audUserId: wA.aud?.userId ?? null,
    audSameScope: wA.audSameScope,
    exports: a,
  };

  // Part B: 50 at once, one per transformation, 50 different users.
  const ids = d.transformations.map((t) => t.id);
  const match = matchUsers(ids, exporters);
  const plan = d.transformations.filter((t) => match.has(t.id)).map((t) => ({ t, u: match.get(t.id) }));
  const startedB = await Promise.all(
    plan.map(({ t, u }) =>
      start(
        call,
        sessions[u],
        { definitionCode: "registers", subjectId: t.id, parameters: { register: "raid" } },
        "csv",
        `mth-proof-${opts.label}-b-${t.code}`,
      ),
    ),
  );
  const dl = deadline();
  const b = await Promise.all(
    plan.map(({ t, u }, i) => {
      const w = witnesses(t.id, u);
      return prove(
        call,
        { requester: sessions[u], other: w.other, aud: w.aud },
        { definitionCode: "registers", subjectId: t.id, parameters: { register: "raid" } },
        "csv",
        null,
        opts.pollMs,
        dl,
        startedB[i],
      ).then((r) => ({ ...r, transformation: t.code, audSameScope: w.audSameScope }));
    }),
  );
  const distinctUsers = new Set(plan.map((p) => p.u)).size;
  report.partB = {
    transformations: d.transformations.length,
    matched: plan.length,
    distinctUsers,
    failures:
      plan.length === 50 && distinctUsers === 50
        ? []
        : [`only ${plan.length} transformations matched to ${distinctUsers} distinct users (need 50)`],
    exports: b,
  };

  const all = [...a, ...b];
  const ms = (k) => all.map((r) => r[k]).filter((v) => typeof v === "number");
  const summarize = (list, k) => {
    const v = list
      .map((r) => r[k])
      .filter((x) => typeof x === "number")
      .map((x) => Math.round(x * 1000));
    return {
      count: v.length,
      p50Ms: nearestRank(v, 50) === null ? null : nearestRank(v, 50) / 1000,
      p95Ms: nearestRank(v, 95) === null ? null : nearestRank(v, 95) / 1000,
      maxMs: v.length === 0 ? null : Math.max(...v) / 1000,
    };
  };
  report.summary = {
    exports: all.length,
    failed: all.filter((r) => r.failures.length > 0).length + (report.partB.failures.length > 0 ? 1 : 0),
    startA: summarize(a, "startMs"),
    startB: summarize(b, "startMs"),
    completionA: summarize(a, "completionMs"),
    completionB: summarize(b, "completionMs"),
    largestFileBytes: Math.max(0, ...ms("fileSizeBytes")),
    reopenCandidates: all.filter((r) => r.reopenCandidate).length,
  };
  report.finishedAt = new Date().toISOString();
  return report;
}

async function main() {
  const { values } = parseArgs({
    options: {
      sessions: { type: "string" },
      "base-url": { type: "string" },
      "db-url": { type: "string" },
      out: { type: "string" },
      label: { type: "string", default: "proof" },
      "poll-ms": { type: "string", default: "250" },
      "timeout-s": { type: "string", default: "900" },
    },
  });
  if (!values.sessions || !values["base-url"] || !values["db-url"] || !values.out) {
    console.error("usage: export-proof.mjs --sessions FILE --base-url URL --db-url URL --out FILE [--label L]");
    process.exit(2);
  }
  let report;
  try {
    report = await runProof({
      sessions: values.sessions,
      baseUrl: values["base-url"],
      dbUrl: values["db-url"],
      label: values.label,
      pollMs: Number(values["poll-ms"]),
      timeoutS: Number(values["timeout-s"]),
    });
  } catch (e) {
    console.error(String(e?.stack ?? e));
    process.exit(2);
  }
  writeFileSync(values.out, `${JSON.stringify(report, null, 2)}\n`);
  const s = report.summary;
  console.log(`mth-load export-proof ${report.label}: ${s.exports} exports, ${s.failed} failed`);
  console.log(
    `  part A (${report.partA.transformation}, ${report.partA.initiatives} initiatives): ${report.partA.exports.length} exports`,
  );
  for (const r of report.partA.exports)
    console.log(
      `    ${r.definitionCode}${r.register ? `/${r.register}` : ""} ${r.format}: start ${r.startStatus} ${r.startMs} ms, ` +
        `done ${r.finalStatus} in ${r.completionMs} ms, ${r.fileSizeBytes} bytes, percents ${(r.percents ?? []).join(",")}, ` +
        `other ${JSON.stringify(r.sameScopeOtherStatuses)}, aud ${JSON.stringify(r.audStatuses)}` +
        (r.failures.length ? `  FAIL: ${r.failures.join("; ")}` : ""),
    );
  console.log(
    `  part B: ${report.partB.matched} transformations, ${report.partB.distinctUsers} distinct users, at once`,
  );
  for (const r of report.partB.exports.filter((x) => x.failures.length > 0))
    console.log(`    ${r.transformation} FAIL: ${r.failures.join("; ")}`);
  for (const f of report.partB.failures) console.log(`    FAIL: ${f}`);
  console.log(`  start A ${JSON.stringify(s.startA)}`);
  console.log(`  start B ${JSON.stringify(s.startB)}`);
  console.log(`  completion A ${JSON.stringify(s.completionA)}`);
  console.log(`  completion B ${JSON.stringify(s.completionB)}`);
  console.log(`  largest file ${s.largestFileBytes} bytes; EXPORT_MAX_BYTES reopen candidates ${s.reopenCandidates}`);
  process.exit(s.failed === 0 ? 0 : 1);
}

if (import.meta.url === `file://${process.argv[1]}`) await main();
